{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C19"],
      "claim": "In cirrhotic liver patients, meptazinol absolute oral bioavailability was 27.9 ± 5.3% after a 200 mg oral dose, exceeding the 20% threshold under the query condition.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Cilomilast absolute oral bioavailability was 96% (range 92–102%) in healthy fasted male volunteers, strongly above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Irbesartan absolute oral bioavailability is about 70% in patients, well above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Direct cirrhosis-condition evidence shows an absolute oral bioavailability of 27.9%, above the 20% threshold, and multiple human absolute bioavailability measurements are 60–100%. Confidence is moderate because only one direct cirrhosis record is available and most other evidence comes from healthy subjects.",
  "evidence_gaps": [
    "Only one direct cirrhosis-condition absolute bioavailability record is available; other evidence is from healthy subjects or unspecified conditions.",
    "Healthy-volunteer meptazinol records show low oral bioavailability, so the cirrhosis-related increase may be compound-specific and may not transfer directly to the query.",
    "Some supporting records are qualitative or estimated, but the main claims rely on absolute numeric measurements."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

